use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-lower-bound-c7a");let source=Path::new("/tmp/zopro-grouping-lower-bound/candidate");let mut pins:BTreeMap<String,String>=serde_json::from_value(read("/tmp/zopro-grouping-lower-bound/source-pins.json")).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}
 let accepted=read("/tmp/zopro-ready-c7a/native/accepted/artifacts.json");assert_eq!(hash(accepted["binary"].as_str().unwrap()),accepted["binary_sha256"].as_str().unwrap());for(p,h)in accepted["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),h.as_str().unwrap().into());}
 for(label,n)in[("field",33),("core",109)]{let p=format!("/tmp/zopro-ready-c7a/native/accepted-{label}/tests.json");let t=read(&p);assert_eq!(t["passed_tests"].as_array().unwrap().len(),n);pins.insert(p.clone(),hash(p));}pins.insert(accepted["binary"].as_str().unwrap().into(),accepted["binary_sha256"].as_str().unwrap().into());
 let mut plan=read("/tmp/zopro-grouping-lower-bound/native-plan.json");plan["source_pins"]=json!(r.join("build-pins.json"));let rendered=serde_json::to_string(&plan).unwrap().replace("/tmp/zopro-grouping-lower-bound/target-sdk-on","/tmp/zopro-lower-bound-c7a/target-candidate").replace("/tmp/zopro-grouping-lower-bound/native/on-libraries","/tmp/zopro-lower-bound-c7a/native/on-libraries").replace("target-cpu=native","target-cpu=znver4");plan=serde_json::from_str(&rendered).unwrap();plan["steps"][5]["rustc_flags"]=json!(["-O","-C","target-cpu=znver4","-C","lto=fat","-C","codegen-units=1"]);
 for p in [r.join("design.md"),r.join("prepare-build.rs"),source.join("crates/zopro-core/src/msm_affine/grouping/lower_bound.rs")]{pins.insert(p.display().to_string(),hash(p));}fs::write(r.join("build-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();fs::write(r.join("native-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("Pinned existing accepted znver4 SDK; fresh identical-candidate target build with{}pins",pins.len());}
